    public static let dark: [TerminalTheme] = all.filter { $0.isDark }

    /// All 32 light themes
    public static let light: [TerminalTheme] = all.filter { !$0.isDark }

    /// Dictionary lookup by theme ID (e.g. "catppuccin-mocha", "github-dark")
    public static let byId: [String: TerminalTheme] = Dictionary(uniqueKeysWithValues: all.map { ($0.id, $0) })

    /// Unique theme family names in alphabetical order (36 families)
    public static let families: [String] = Array(Set(all.map { $0.themeFamily })).sorted()
